            padding: 0; /* 改为0，因为立绘需要紧贴上边缘 */
            text-align: center;
            box-shadow: 0 5px 15px rgba(0,0,0,0.2);
            transition: all 0.3s ease;
            position: relative;
            overflow: hidden;
        }

        .relationship-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 8px 20px rgba(0,0,0,0.3);
        }

        .relationship-info {
            padding: clamp(10px, 2vw, 15px);
        }

        .relationship-portrait {
            width: 100%;
            height: auto;
            position: relative;
            overflow: hidden;
            margin-bottom: clamp(5px, 1vw, 8px);
        }

        .relationship-portrait img {
            width: 100%;
            height: auto;
            display: block;
            object-fit: cover;
            object-position: top center;
        }

        .relationship-name {
            font-size: clamp(0.8rem, 2vw, 1rem);
            font-weight: bold;
            margin-bottom: clamp(8px, 1.5vw, 10px);
            color: #2c2c2c;
        }

        .relationship-bar {
            width: 100%;
            height: clamp(15px, 3vw, 20px);
            background: #e0e0e0;
            border-radius: 10px;
            overflow: hidden;
            margin-bottom: 5px;
        }

        .relationship-fill {
            height: 100%;
            background: linear-gradient(to right, #ff6b6b, #4ecdc4);
            transition: width 0.5s ease;
        }

        .relationship-value {
            font-size: clamp(0.7rem, 1.8vw, 0.875rem);
            color: #666;
        }

        /* 弹窗 - 响应式改进 */
        .modal {
            display: none;
            position: absolute;
            z-index: 2000;
            left: 0;
            top: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0,0,0,0.5);
            padding: 20px;
        }

        .modal-content {
            background-color: #fff;
            margin: auto;
            padding: clamp(20px, 4vw, 30px);
            border: 3px solid #2c2c2c;
            width: min(400px, 100%);
            max-width: 90%;
            max-height: 80%;
            overflow-y: auto;
            text-align: center;
            border-radius: 10px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.3);
            position: absolute;  /* 改为absolute定位 */
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);  /* 居中定位 */
        }

        .modal-text {
            font-size: clamp(1rem, 2.5vw, 1.25rem);
            font-weight: bold;
            color: #2c2c2c;
            margin-bottom: clamp(15px, 3vw, 20px);
            line-height: 1.6;
        }

        .modal-buttons {
            display: flex;
            gap: clamp(10px, 2vw, 15px);
            justify-content: center;
            flex-wrap: wrap;
        }

        .modal-btn {
            padding: clamp(8px, 2vw, 10px) clamp(20px, 4vw, 30px);
            background: #2c2c2c;
            color: #fff;
            border: none;
            border-radius: 5px;
            cursor: pointer;
            font-size: clamp(0.8rem, 2vw, 1rem);
            font-weight: bold;
        }

        .modal-btn:hover {
            background: #3c3c3c;
        }

        .modal-btn.cancel {
            background: #666;
        }

        .modal-btn.cancel:hover {
            background: #555;
        }

        /* 输入框样式 */
        .input-area {
            margin: clamp(15px, 3vw, 20px) 0;
        }

        .input-field {
            width: 100%;
            padding: clamp(8px, 2vw, 10px);
            font-size: clamp(0.8rem, 2vw, 1rem);
            border: 2px solid #2c2c2c;
            border-radius: 5px;
            resize: vertical;
            min-height: clamp(80px, 15vw, 100px);
            max-height: 200px;
            font-family: "Microsoft YaHei", "SimSun", serif;
        }

        .input-field:focus {
            outline: none;
            border-color: #4ecdc4;
        }

        /* 互动内容自动换行样式 */
        .interaction-content {
            word-wrap: break-word;
            word-break: break-all;
            white-space: pre-wrap;
            text-align: left;
            max-width: 100%;
            display: inline-block;
        }

        /* 故事区域 */
        .story-area {
            width: 100%;
            max-width: 100%;  /* 全部改为动态宽度 */
            margin: 0 auto;
            background: #fff;
            border: 3px solid #2c2c2c;
            border-top: none;
            padding: clamp(15px, 3vw, 25px);
            min-height: clamp(120px, 20vw, 180px);
            box-shadow: 0 10px 30px rgba(0,0,0,0.3);
            box-sizing: border-box;
        }

        /* 故事文本 */
        .story-text {
            font-size: clamp(0.9rem, 2.2vw, 1.125rem);
            line-height: 1.8;
            color: #2c2c2c;
            text-indent: 2em;
            font-family: "Microsoft YaHei", "SimSun", serif;
        }

        /* 水墨效果装饰 */
        .ink-decoration {
            position: absolute;
            width: clamp(60px, 12vw, 100px);
            height: clamp(60px, 12vw, 100px);
            background: radial-gradient(circle, rgba(0,0,0,0.1) 0%, transparent 70%);
            border-radius: 50%;
            pointer-events: none;
        }

        .ink1 { top: 10%; right: 10%; }
        .ink2 { bottom: 10%; left: 5%; }

        /* 滚动条样式 */
        .stats-container::-webkit-scrollbar,
        .relationships-container::-webkit-scrollbar {
            width: 8px;
        }

        .stats-container::-webkit-scrollbar-track,
        .relationships-container::-webkit-scrollbar-track {
            background: #f1f1f1;
            border-radius: 4px;
        }

        .stats-container::-webkit-scrollbar-thumb,
        .relationships-container::-webkit-scrollbar-thumb {
            background: #888;
            border-radius: 4px;
        }

        .stats-container::-webkit-scrollbar-thumb:hover,
        .relationships-container::-webkit-scrollbar-thumb:hover {
            background: #555;
        }

        /* 21点游戏iframe弹窗 - 新增 */
        .blackjack-modal {
            display: none;
            position: absolute;  /* 从fixed改为absolute */
            z-index: 3000;
            left: 0;
            top: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0,0,0,0.7);
        }

        .blackjack-container {
            width: 100%;  /* 改为100% */
            height: 100%;  /* 改为100% */
            margin: 0;  /* 移除margin */
            position: relative;
        }

        .blackjack-iframe {
            width: 100%;
            height: 100%;
            border: none;
            border-radius: 10px;
        }

        /* 响应式调整 */
        @media (max-width: 840px) {
            .container {
                padding: 0;
            }

            .viewport-wrapper {
                max-width: 100%;
            }
        }

        @media (max-width: 600px) {
            /* 移动端关系卡片网格调整 */
            .relationship-grid {
                grid-template-columns: repeat(3, 1fr);
                gap: 8px;
            }

            .relationship-card {
                padding: 0; /* 确保为0 */
            }

            .relationship-info {
                padding: 5px;
            }

            .relationship-name {
                font-size: 0.7rem;
            }

        }

        /* 随机事件框样式 - 响应式优化 */
        .random-event-container {
            background: rgba(44, 44, 44, 0.95);
            border: 2px solid #4ecdc4;
            border-radius: 10px;
            padding: clamp(12px, 3vw, 20px);
            margin-top: clamp(12px, 3vw, 20px);
            box-shadow: 0 5px 15px rgba(0,0,0,0.3);
            display: none;
        }

        .random-event-container.show {
            display: block;
        }

        .event-title {
            font-size: clamp(1rem, 2.5vw, 1.25rem);
            font-weight: bold;
            color: #4ecdc4;
            margin-bottom: clamp(6px, 1.5vw, 10px);
            text-align: center;
        }

        .event-description {
            font-size: clamp(0.875rem, 2vw, 1rem);
            color: #fff;
            margin-bottom: clamp(12px, 3vw, 20px);
            line-height: 1.5;
            text-align: center;
        }

        .event-options {
            display: flex;
            flex-direction: column;
            gap: clamp(8px, 2vw, 15px);
        }

        .event-option-btn {
            background: #2c2c2c;
            border: 2px solid #4ecdc4;
            border-radius: 8px;
            padding: clamp(10px, 2.5vw, 15px);
            cursor: pointer;
            transition: all 0.3s ease;
            text-align: left;
        }

        .event-option-btn:hover {
            background: #3c3c3c;
            transform: translateY(-2px);
            box-shadow: 0 5px 15px rgba(78, 205, 196, 0.3);
        }

        .option-desc {
            font-size: clamp(0.875rem, 2vw, 1rem);
            color: #fff;
            margin-bottom: clamp(5px, 1vw, 8px);
            line-height: 1.4;
        }

        .option-reward {
            font-size: clamp(0.75rem, 1.8vw, 0.875rem);
            color: #4ecdc4;
            margin-bottom: clamp(3px, 0.8vw, 5px);
        }

        .option-success-rate {
            font-size: clamp(0.75rem, 1.8vw, 0.875rem);
            color: #aaa;
        }

        /* 小屏幕优化 */
        @media (max-width: 600px) {
            .random-event-container {
                margin-top: 10px;
                padding: 10px;
            }

            .event-options {
                gap: 6px;
            }

            .event-option-btn {
                padding: 8px 10px;
                border-radius: 6px;
            }

            /* 在非常小的屏幕上，减少行间距 */
            .option-desc {
                margin-bottom: 3px;
            }

            .option-reward {
                margin-bottom: 2px;
            }
        }

        /* 横屏手机优化 */
        @media (max-height: 500px) and (orientation: landscape) {
            .random-event-container {
                padding: 8px 12px;
                margin-top: 8px;
            }

            .event-title {
                margin-bottom: 5px;
            }

            .event-description {
                margin-bottom: 8px;
            }

            .event-options {
                gap: 5px;
            }

            .event-option-btn {
                padding: 6px 10px;
            }
        }

        /* 平板和小窗口优化 */
        @media (min-width: 600px) and (max-width: 840px) {
            .random-event-container {
                padding: 15px;
                margin-top: 15px;
            }

            .event-options {
                gap: 10px;
            }

            .event-option-btn {
                padding: 12px;
            }
        }

        /* 战斗信息框样式 */
        .battle-event-container {
            background: rgba(44, 44, 44, 0.95);
            border: 2px solid #ff4d6d;
            border-radius: 10px;
            padding: clamp(12px, 3vw, 20px);
            margin-top: clamp(12px, 3vw, 20px);
            box-shadow: 0 5px 15px rgba(0,0,0,0.3);
            display: none;
        }

        .battle-event-container.show {
            display: block;
        }

        .battle-event-title {
            font-size: clamp(1rem, 2.5vw, 1.25rem);
            font-weight: bold;
            color: #ff4d6d;
            margin-bottom: clamp(6px, 1.5vw, 10px);
            text-align: center;
        }

        .battle-event-description {
            font-size: clamp(0.875rem, 2vw, 1rem);
            color: #fff;
            margin-bottom: clamp(12px, 3vw, 20px);
            line-height: 1.5;
            text-align: center;
        }

        .battle-enemy-info {
            background: rgba(0, 0, 0, 0.5);
            padding: clamp(10px, 2vw, 15px);
            border-radius: 8px;
            margin-bottom: clamp(10px, 2vw, 15px);
        }

        .enemy-info-item {
            font-size: clamp(0.8rem, 1.8vw, 0.9rem);
            color: #ccc;
            margin: clamp(3px, 0.8vw, 5px) 0;
        }

        .enemy-info-label {
            color: #ff4d6d;
            font-weight: bold;
        }

        .battle-reward {
            background: rgba(78, 205, 196, 0.2);
            padding: clamp(8px, 2vw, 12px);
            border-radius: 6px;
            margin-bottom: clamp(12px, 3vw, 20px);
            text-align: center;
        }

        .battle-reward-text {
            font-size: clamp(0.875rem, 2vw, 1rem);
            color: #4ecdc4;
        }

        .battle-actions {
            display: flex;
            gap: clamp(10px, 2vw, 15px);
            justify-content: center;
        }

        .battle-action-btn {
            flex: 1;
            padding: clamp(8px, 2vw, 12px) clamp(20px, 4vw, 30px);
            border: 2px solid #ff4d6d;
            border-radius: 8px;
            cursor: pointer;
            font-size: clamp(0.875rem, 2vw, 1rem);
            font-weight: bold;
            transition: all 0.3s ease;
        }

        .battle-action-btn.fight {
            background: #ff4d6d;
            color: #fff;
        }

        .battle-action-btn.fight:hover {
            background: #ff6b87;
            transform: translateY(-2px);
        }

        .battle-action-btn.flee {
            background: #2c2c2c;
            color: #fff;
            border-color: #666;
        }

        .battle-action-btn.flee:hover {
            background: #3c3c3c;
            transform: translateY(-2px);
        }

        /* 战斗iframe弹窗 */
        .battle-modal {
            display: none;
            position: absolute;  /* 从fixed改为absolute */
            z-index: 3000;
            left: 0;
            top: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0,0,0,0.7);
        }

        .battle-container {
            width: 100%;  /* 改为100% */
            height: 100%;  /* 改为100% */
            margin: 0;  /* 移除margin */
            position: relative;
        }

        .battle-iframe {
            width: 100%;
            height: 100%;
            border: none;
            border-radius: 10px;
        }
        /* 自由行动输入框容器 */
        .free-action-container {
            width: 100%;
            max-width: 100%;  /* 全部改为动态宽度 */
            margin: 0 auto;
            background: #fff;
            border: 3px solid #2c2c2c;
            border-bottom: none;
            padding: clamp(10px, 2vw, 15px);
            display: flex;
            gap: 10px;
            align-items: flex-start;
            box-sizing: border-box;
        }

        /* 自由行动输入框 */
        .free-action-input {
            flex: 1;
            min-height: 36px;
            max-height: 120px;
            padding: clamp(6px, 1.5vw, 10px) clamp(10px, 2vw, 15px);
            font-size: clamp(0.8rem, 2vw, 1rem);
            font-family: "Microsoft YaHei", "SimSun", serif;
            border: 2px solid #ddd;
            border-radius: 5px;
            resize: none;
            overflow-y: auto;
            line-height: 1.4;
            transition: border-color 0.3s ease;
        }

        .free-action-input:focus {
            outline: none;
            border-color: #4ecdc4;
        }

        .free-action-input::placeholder {
            color: #999;
        }

        /* 发送按钮 */
        .free-action-send-btn {
            padding: clamp(8px, 2vw, 12px) clamp(20px, 4vw, 30px);
            background: #2c2c2c;
            color: #fff;
            border: 2px solid #1a1a1a;
            border-radius: 5px;
            cursor: pointer;
            font-size: clamp(0.8rem, 2vw, 1rem);
            font-weight: bold;
            transition: all 0.3s ease;
            white-space: nowrap;
            min-height: 36px;
        }

        .free-action-send-btn:hover {
            background: #3c3c3c;
            transform: translateY(-1px);
        }

        .free-action-send-btn:active {
            transform: translateY(0);
        }

        /* 响应式调整 */
        @media (max-width: 600px) {
            .free-action-container {
                padding: 8px;
                gap: 8px;
            }

            .free-action-input {
                min-height: 32px;
                font-size: 0.8rem;
            }

            .free-action-send-btn {
                padding: 8px 15px;
                min-height: 32px;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <!-- 视窗区域增加包装器 -->
        <div class="viewport-wrapper">
            <div class="viewport" id="main-viewport">
                <!-- 悬浮提示框 -->
                <div class="tooltip" id="tooltip"></div>

                <!-- NPC信息弹窗 -->
                <div class="npc-info-popup" id="npc-info-popup"></div>

                <!-- 地点信息弹窗 - 新增 -->
                <div class="location-info-popup" id="location-info-popup"></div>

                <!-- 地图场景 -->
                <div id="map-scene" class="scene active">
                    <div class="status-display">
                        <div class="date-display" id="date-display">第1年第1月第1周</div>
                        <div class="mood-display" id="mood-display">心情: 100</div>
                        <div class="action-points-display" id="action-points-display">行动点: 3</div>
                    </div>
                    <button class="refresh-npc-btn" onclick="refreshNpcLocations()">刷新NPC位置</button>
                    <div class="location" id="yanwuchang"></div>
                    <div class="location" id="cangjingge"></div>
                    <div class="location" id="huofang"></div>
                    <div class="location" id="houshan"></div>
                    <div class="location" id="yishiting"></div>
                    <div class="location" id="tiejiangpu"></div>
                    <div class="location" id="nandizi"></div>
                    <div class="location" id="nvdizi"></div>
                    <div class="location" id="shanmen"></div>
                    <div class="ink-decoration ink1"></div>
                    <div class="ink-decoration ink2"></div>
                </div>

                <!-- 后续场景保持不变 -->
                <!-- 角色属性场景 -->
                <div id="player-stats-scene" class="scene">
                    <button class="back-btn" onclick="backToMap()">返回</button>
                    <div class="stats-container">
                        <div class="stats-group">
                            <h3>天赋属性</h3>
                            <div class="stat-item">
                                <span class="stat-name">根骨</span>
                                <div class="stat-bar">
                                    <div class="stat-fill" id="talent-gengu" style="width: 75%"></div>
                                </div>
                                <span class="stat-value" id="talent-gengu-value">75</span>
                            </div>
                            <div class="stat-item">
                                <span class="stat-name">悟性</span>
                                <div class="stat-bar">
                                    <div class="stat-fill" id="talent-wuxing" style="width: 82%"></div>
                                </div>
                                <span class="stat-value" id="talent-wuxing-value">82</span>
                            </div>
                            <div class="stat-item">
                                <span class="stat-name">心性</span>
                                <div class="stat-bar">
                                    <div class="stat-fill" id="talent-xinxing" style="width: 68%"></div>
                                </div>
                                <span class="stat-value" id="talent-xinxing-value">68</span>
                            </div>
                            <div class="stat-item">
                                <span class="stat-name">魅力</span>
                                <div class="stat-bar">
                                    <div class="stat-fill" id="talent-meili" style="width: 70%"></div>
                                </div>
                                <span class="stat-value" id="talent-meili-value">70</span>
                            </div>
                        </div>

                        <div class="bottom-stats-row">
                            <div class="stats-group">
                                <h3>人物数值</h3>
                                <div class="simple-stat-item">
                                    <span class="simple-stat-name">武学</span>
                                    <span class="simple-stat-value" id="stat-wuxue-value">50</span>
                                </div>
                                <div class="simple-stat-item">
                                    <span class="simple-stat-name">学识</span>
                                    <span class="simple-stat-value" id="stat-xueshi-value">35</span>
                                </div>
                                <div class="simple-stat-item">
                                    <span class="simple-stat-name">声望</span>
                                    <span class="simple-stat-value" id="stat-shengwang-value">20</span>
                                </div>
                                <div class="simple-stat-item">
                                    <span class="simple-stat-name">金钱</span>
                                    <span class="simple-stat-value" id="stat-jinqian-value">100</span>
                                </div>
                            </div>

                            <div class="stats-group">
                                <h3>战斗数值</h3>
                                <div class="simple-stat-item">
                                    <span class="simple-stat-name">攻击力</span>
                                    <div class="point-control">
                                        <span class="simple-stat-value" id="combat-attack-value">20</span>
                                        <button class="add-point-btn" id="add-attack-btn" onclick="addAttack()">+</button>
                                    </div>
                                </div>
                                <div class="simple-stat-item">
                                    <span class="simple-stat-name">生命值</span>
                                    <div class="point-control">
                                        <span class="simple-stat-value" id="combat-hp-value">50</span>
                                        <button class="add-point-btn" id="add-hp-btn" onclick="addHP()">+</button>
                                    </div>
                                </div>
                                <div class="simple-stat-item">
                                    <span class="simple-stat-name">剩余点数</span>
                                    <span class="simple-stat-value" id="remaining-points-value">0</span>
                                </div>
                                <div class="skill-list">
                                    <div class="simple-stat-name" style="margin-bottom: 10px;">已学武功</div>
                                    <div id="learned-skills"></div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <!-- 人际关系场景 -->
                <div id="relationships-scene" class="scene">
                    <button class="back-btn" onclick="backToMap()">返回</button>
                    <div class="relationships-container">
                        <div class="relationship-grid" id="relationship-grid">
                            <!-- 动态生成 -->
                        </div>
                    </div>
                </div>

                <!-- 各个场景 -->
                <div id="yanwuchang-scene" class="scene">
                    <button class="back-btn" onclick="backToMap()">返回</button>
                    <div class="scene-title">演武场</div>
                    <div class="npc-container" id="yanwuchang-npcs"></div>
                    <div class="scene-actions">
                        <button class="scene-btn" onclick="performAction('练武', 'yanwuchang')">练武</button>
                    </div>
                </div>

                <div id="cangjingge-scene" class="scene">
                    <button class="back-btn" onclick="backToMap()">返回</button>
                    <div class="scene-title">藏经阁</div>
                    <div class="npc-container" id="cangjingge-npcs"></div>
                    <div class="scene-actions">
                        <button class="scene-btn" onclick="performAction('学习', 'cangjingge')">学习</button>
                    </div>
                </div>

                <div id="huofang-scene" class="scene">
                    <button class="back-btn" onclick="backToMap()">返回</button>
                    <div class="scene-title">伙房</div>
