                radial-gradient(circle at 20% 80%, rgba(0,0,0,0.1) 0%, transparent 50%),
                radial-gradient(circle at 80% 20%, rgba(0,0,0,0.05) 0%, transparent 50%);
            box-sizing: border-box;
