                                </div>
                                <span class="stat-value" id="talent-meili-value">70</span>
                            </div>
                        </div>

                        <div class="bottom-stats-row">
                            <div class="stats-group">
                                <h3>人物数值</h3>
                                <div class="simple-stat-item">
