        // 根据武学值计算获得的等级（点数）
        function calculateLevelFromWuxue(wuxue) {
            let totalWuxue = 0;
            let level = 0;

            // 从5点开始，每级需要的武学值递增1
            // 第1级需要5点，第2级需要6点，第3级需要7点...
            for (let i = 1; i <= 20; i++) { // 最多20级，对应290点武学值
                const requiredWuxue = 4 + i;
                if (totalWuxue + requiredWuxue <= wuxue) {
                    totalWuxue += requiredWuxue;
                    level = i;
                } else {
                    break;
                }
            }

            return level;
        }

        // 计算达到某个等级需要的总武学值
        function calculateWuxueForLevel(level) {
            let totalWuxue = 0;
            for (let i = 1; i <= level; i++) {
                totalWuxue += (4 + i);
            }
            return totalWuxue;
        }

        // 计算剩余分配点数 - 使用新的递增难度系统
        function calculateRemainingPoints() {
            // 根据武学值计算获得的等级
            const earnedLevels = calculateLevelFromWuxue(playerStats.武学);

            // 计算已经使用的点数
