        // 处理事件选项 - 新增
        async function handleEventOption(optionIndex, option) {
            if (!currentRandomEvent) return;

            // 计算成功率
            const successRate = parseInt(option.成功率) / 100;
            const isSuccess = Math.random() < successRate;

            // 如果成功，应用奖励
            if (isSuccess && option.奖励) {
                applyEventReward(option.奖励);
            }

            // 构建结果信息
            const resultMessage = `事件描述: ${currentRandomEvent.事件描述}<br>` +
                `{{user}}行动选择: ${option.描述}<br>` +
                `选择结果: ${isSuccess ? '成功' : '失败'}`;

            // 隐藏随机事件
            hideRandomEvent();

            // 使用新的消息处理函数
            await handleMessageOutput(resultMessage);
        }

        // 应用事件奖励 - 新增
        function applyEventReward(reward) {
            // 解析奖励字符串，例如 "悟性+3"
            const rewardMatch = reward.match(/(.+?)([+-])(\d+)/);
            if (rewardMatch) {
                const attribute = rewardMatch[1];
                const operation = rewardMatch[2];
                const value = parseInt(rewardMatch[3]);

                // 检查是否是天赋属性
                if (playerTalents.hasOwnProperty(attribute)) {
                    if (operation === '+') {
                        playerTalents[attribute] = Math.min(100, playerTalents[attribute] + value);
                    } else {
                        playerTalents[attribute] = Math.max(0, playerTalents[attribute] - value);
                    }
                    checkAllValueRanges();
                    updateStatsDisplay();
                }
                // 检查是否是其他属性
                else if (playerStats.hasOwnProperty(attribute)) {
                    if (operation === '+') {
                        playerStats[attribute] = playerStats[attribute] + value;
                    } else {
                        playerStats[attribute] = Math.max(0, playerStats[attribute] - value);
                    }
                    checkAllValueRanges();
                    updateStatsDisplay();
                }
            }
        }

        // 显示战斗事件
        function displayBattleEvent(event) {
            const container = document.getElementById('battle-event-container');
            const description = document.getElementById('battle-event-description');
            const enemyName = document.getElementById('enemy-name-display');
            const enemyAttack = document.getElementById('enemy-attack-display');
            const enemyHealth = document.getElementById('enemy-health-display');
            const rewardText = document.getElementById('battle-reward-text');

            // 保存当前战斗事件
            currentBattleEvent = event;

            // 设置事件描述
            description.textContent = event.事件描述;

            // 设置敌人信息
            if (event.敌方信息) {
                enemyName.textContent = event.敌方信息.名称 || '未知敌人';
                enemyAttack.textContent = event.敌方信息.属性?.攻击力 || '中';
                enemyHealth.textContent = event.敌方信息.属性?.生命力 || '中';

                // 设置奖励信息
                if (event.敌方信息.战斗报酬) {
                    const reward = event.敌方信息.战斗报酬;
                    rewardText.textContent = `战斗胜利奖励：${reward.类型}+${reward.数值}`;
                    currentBattleReward = reward;
                }
            }

            // 显示容器
            container.classList.add('show');
        }

        // 隐藏战斗事件
        function hideBattleEvent() {
            const container = document.getElementById('battle-event-container');
            container.classList.remove('show');
            currentBattleEvent = null;
        }

        // 发起战斗
        function startBattle() {
            if (!currentBattleEvent || !currentBattleEvent.敌方信息) return;

            const enemyInfo = currentBattleEvent.敌方信息;
            currentBattleType = 'event';

            // 准备战斗数据
            const battleData = {
                player: {
                    name: '你',
                    attack: combatStats.攻击力,
                    health: combatStats.生命值
                },
                enemy: {
                    name: enemyInfo.名称,
                    maxHealth: enemyInfo.属性?.生命力 || '中',
                    basicDamage: enemyInfo.属性?.攻击力 || '中'
                }
            };

            // 显示战斗iframe
            showBattleGame(battleData);
        }

        // 放弃战斗
        async function fleeBattle() {
            if (!currentBattleEvent) return;

            const resultMessage = currentBattleEvent.事件描述 + '<br><br>你选择避开了战斗';

            // 隐藏战斗事件
            hideBattleEvent();

            // 使用新的消息处理函数
            await handleMessageOutput(resultMessage);
        }

        // 应用战斗奖励
        function applyBattleReward(reward) {
            if (!reward) return;

            switch (reward.类型) {
                case '金钱':
                    playerStats.金钱 += reward.数值;
                    break;
                case '声望':
                    playerStats.声望 += reward.数值;
                    break;
                case '武学':
                    playerStats.武学 += reward.数值;
                    break;
                case '学识':
                    playerStats.学识 += reward.数值;
                    break;
            }
            checkAllValueRanges();
            updateStatsDisplay();
        }

        // 更新故事文本（保持原有正文不被覆盖）
        // 使用markdown-it的版本
        function updateStoryText(text) {
            const storyElement = document.getElementById('story-text');

            // 初始化markdown-it，禁用删除线
            const md = window.markdownit({
                html: true,
                breaks: true,
                linkify: true,
                typographer: true
            }).disable('strikethrough');  // 禁用删除线功能

            // 使用markdown-it解析
            const htmlContent = md.render(text);

            // 使用innerHTML设置内容
            storyElement.innerHTML = htmlContent;

            // 添加淡入动画效果
            storyElement.style.opacity = '0';
            setTimeout(() => {
                storyElement.style.transition = 'opacity 0.5s ease';
                storyElement.style.opacity = '1';
            }, 100);
        }

        // 刷新NPC位置（限制每个地点最多2个NPC）
        function refreshNpcLocations() {
            // 记录每个地点的NPC数量
            const locationCount = {
                yanwuchang: 0,
                cangjingge: 0,
                huofang: 0,
                houshan: 0,
                yishiting: 0,
                tiejiangpu: 0,
                nandizi: 0,
                nvdizi: 0,
                shanmen: 0
            };

            // 为每个NPC重新分配位置
            const npcOrder = ['A', 'B', 'C', 'D', 'E', 'F', 'G'].sort(() => Math.random() - 0.5);

            npcOrder.forEach(npcId => {
                let assigned = false;
                let attempts = 0;
                const maxAttempts = 20;

                while (!assigned && attempts < maxAttempts) {
                    const location = getRandomLocation(npcId);

                    if (location === 'none') {
                        currentNpcLocations[npcId] = location;
                        assigned = true;
                    } else if (locationCount[location] < 2) {  // 修改为最多2个NPC
                        currentNpcLocations[npcId] = location;
                        locationCount[location]++;
                        assigned = true;
                    }

                    attempts++;
                }

                if (!assigned) {
                    currentNpcLocations[npcId] = 'none';
                }
            });

            // 更新各个NPC的位置变量
            npcLocationA = currentNpcLocations.A;
            npcLocationB = currentNpcLocations.B;
            npcLocationC = currentNpcLocations.C;
            npcLocationD = currentNpcLocations.D;
            npcLocationE = currentNpcLocations.E;
            npcLocationF = currentNpcLocations.F;
            npcLocationG = currentNpcLocations.G;
            const activeScene = document.querySelector('.scene.active');
            if (activeScene && activeScene.id !== 'map-scene') {
                const locationName = activeScene.id.replace('-scene', '');
                displayNpcs(locationName);
            }
        }

        // 根据概率获取NPC的随机位置
        function getRandomLocation(npcId) {
            const probabilities = npcLocationProbability[npcId];
            const random = Math.random();
            let cumulative = 0;

            for (const location in probabilities) {
                cumulative += probabilities[location];
                if (random <= cumulative) {
                    return location;
                }
            }

            return 'none';
        }

        // 获取某个地点的NPC列表
        function getNpcsAtLocation(location) {
            const npcsAtLocation = [];

            Object.keys(currentNpcLocations).forEach(npcId => {
                if (currentNpcLocations[npcId] === location) {
                    npcsAtLocation.push({ id: npcId, ...npcs[npcId] });
                }
            });

            return npcsAtLocation;
        }

        // 显示NPC立绘（支持最多3个NPC，超过3个时随机选择）
        function displayNpcs(location) {
            const container = document.getElementById(location + '-npcs');
            if (!container) return;

            let npcsAtLocation = getNpcsAtLocation(location);
            container.innerHTML = '';

            if (npcsAtLocation.length === 0) {
                return;
            }

            // 如果超过3个NPC，随机选择3个显示
            if (npcsAtLocation.length > 3) {
                // 随机打乱数组
                npcsAtLocation = npcsAtLocation.sort(() => Math.random() - 0.5);
                // 只取前3个
                npcsAtLocation = npcsAtLocation.slice(0, 3);

                console.log(`${location} 有超过3个NPC，随机显示其中3个`);
            }

            npcsAtLocation.forEach((npc, index) => {
                const portrait = document.createElement('div');
                portrait.className = 'npc-portrait';

                // 根据NPC数量设置位置类
                if (npcsAtLocation.length === 1) {
                    portrait.classList.add('single');
                } else if (npcsAtLocation.length === 2) {
                    portrait.classList.add(index === 0 ? 'double-left' : 'double-right');
                } else if (npcsAtLocation.length === 3) {
                    // 3个NPC的布局
                    portrait.style.position = 'absolute';
                    portrait.style.bottom = '0';
                    portrait.style.width = '60%';  // 稍微缩小尺寸
                    portrait.style.height = '60%';

                    // 三个NPC分别在25%、50%、75%的位置
                    const positions = ['25%', '50%', '75%'];
                    portrait.style.left = positions[index];
                    portrait.style.transform = 'translateX(-50%)';

                    // 添加z-index以处理重叠
                    portrait.style.zIndex = index + 1;

                    // // 可选：为中间的NPC稍微调整位置，避免完全重叠
                    // if (index === 1) {
                    //     portrait.style.bottom = '2%'; // 中间的稍微高一点
                    // }
                }

                portrait.innerHTML = `<img src="${npcPortraits[npc.id]}" alt="${npc.name}">`;

                // 添加点击事件
                portrait.addEventListener('click', function(e) {
                    e.stopPropagation();
                    showNpcInfo(npc.id, location, e);
                });

                container.appendChild(portrait);
            });
        }


        // 显示NPC信息弹窗 - 修复位置计算问题
        function showNpcInfo(npcId, location, event) {
            const npc = npcs[npcId];
            const popup = document.getElementById('npc-info-popup');

            popup.innerHTML = `
                <div class="npc-info-name">${npc.name}</div>
                <div class="npc-info-desc">${npc.description}</div>
                <div class="npc-info-actions">
                    <button class="npc-info-btn" onclick="npcAction('${npcId}', '切磋')">切磋</button>
                    <button class="npc-info-btn" onclick="npcAction('${npcId}', '互动')">互动</button>
                </div>
            `;

            // 先显示弹窗以获取其尺寸
            popup.classList.add('show');

            // 获取点击的立绘元素
            const portrait = event.currentTarget;
            const portraitRect = portrait.getBoundingClientRect();

            // 获取弹窗的实际尺寸
            const popupRect = popup.getBoundingClientRect();

            // 计算立绘中心位置
            const portraitCenterX = portraitRect.left + portraitRect.width / 2;
            const portraitCenterY = portraitRect.top + portraitRect.height / 2;

            // 将弹窗定位在立绘中心
            let left = portraitCenterX - popupRect.width / 2;
            let top = portraitCenterY - popupRect.height / 2;

            // 边界检测，确保弹窗不超出窗口
            const margin = 10;
            if (left < margin) {
                left = margin;
            } else if (left + popupRect.width > window.innerWidth - margin) {
                left = window.innerWidth - popupRect.width - margin;
            }

            if (top < margin) {
                top = margin;
            } else if (top + popupRect.height > window.innerHeight - margin) {
                top = window.innerHeight - popupRect.height - margin;
            }

            // 设置最终位置
            popup.style.left = left + 'px';
            popup.style.top = top + 'px';
            popup.style.transform = 'none';

            // 点击其他地方关闭弹窗
            setTimeout(() => {
                document.addEventListener('click', closeNpcInfo);
            }, 100);
        }

        // 关闭NPC信息弹窗
        function closeNpcInfo(e) {
            const popup = document.getElementById('npc-info-popup');
            if (!popup.contains(e.target)) {
                popup.classList.remove('show');
                document.removeEventListener('click', closeNpcInfo);
            }
        }

        // 修改npcAction函数
        function npcAction(npcId, action) {
            // 先关闭信息弹窗
            const popup = document.getElementById('npc-info-popup');
            popup.classList.remove('show');
            document.removeEventListener('click', closeNpcInfo);

            if (action === '互动') {
                const activeScene = document.querySelector('.scene.active');
                const location = activeScene.id.replace('-scene', '');
                showInteractionInput(npcId, location);
            } else if (action === '切磋') {
                const npc = npcs[npcId];
                currentBattleType = 'npc';
                currentBattleNpcName = npc.name;  // 保存NPC名称

                // 准备战斗数据
                const battleData = {
                    player: {
                        name: '你',
                        attack: combatStats.攻击力,
                        health: combatStats.生命值
                    },
                    enemy: {
                        name: npc.name,
                        maxHealth: '中',  // NPC统一设置为中等难度
                        basicDamage: '中'
                    }
                };

                // 显示战斗iframe
                showBattleGame(battleData);
            }
        }

        // 切换到指定场景
        function switchScene(sceneName) {
            const scenes = document.querySelectorAll('.scene');
            scenes.forEach(scene => {
                scene.classList.remove('active');
            });

            const targetScene = document.getElementById(sceneName + '-scene');
            if (targetScene) {
                targetScene.classList.add('active');
                // 更新userLocation
                if (sceneName !== 'player-stats' && sceneName !== 'relationships') {
                    userLocation = sceneName;  // 新增：更新用户位置
                    displayNpcs(sceneName);
                }
            }
            // 不再更新故事文本，保持LLM返回的正文内容
        }

        // 返回地图
        function backToMap() {
            const scenes = document.querySelectorAll('.scene');
            scenes.forEach(scene => {
                scene.classList.remove('active');
            });

            document.getElementById('map-scene').classList.add('active');
            userLocation = 'tianshanpai';  // 新增：在地图界面时设置为天山派
            // 不再更新故事文本，保持LLM返回的正文内容
        }

        // 显示地点信息弹窗 - 修复位置计算，确保在viewport内显示
        function showLocationInfo(locationId, event) {
            const popup = document.getElementById('location-info-popup');
            const locationName = locationNames[locationId];
            const npcsAtLocation = getNpcsAtLocation(locationId);

            let npcsHtml = '';
            if (npcsAtLocation.length > 0) {
                npcsHtml = '<div class="location-info-npcs">在场NPC：';
                // 如果超过3个，显示所有NPC但标注只显示部分
                if (npcsAtLocation.length > 3) {
                    npcsHtml += `<div style="font-size: 0.8em; color: #999; margin: 3px 0;">（共${npcsAtLocation.length}人，随机显示3人）</div>`;
                }
                npcsAtLocation.forEach(npc => {
                    npcsHtml += `<div class="location-info-npc-item">• ${npc.name}</div>`;
                });
                npcsHtml += '</div>';
            } else {
                npcsHtml = '<div class="location-info-npcs">此处暂无人物</div>';
            }

            popup.innerHTML = `
                <div class="location-info-name">${locationName}</div>
                ${npcsHtml}
                <button class="location-go-btn" onclick="goToLocation('${locationId}')">前往</button>
            `;

            // 先显示弹窗以获取其尺寸
            popup.classList.add('show');

            // 获取点击元素和viewport的位置
            const locationElement = event.currentTarget;
            const locationRect = locationElement.getBoundingClientRect();
            const viewportRect = document.querySelector('.viewport').getBoundingClientRect();

            // 获取弹窗的实际尺寸
            const popupRect = popup.getBoundingClientRect();

            // 计算光点中心相对于viewport的位置
            const locationCenterX = locationRect.left + locationRect.width / 2;
            const locationCenterY = locationRect.top + locationRect.height / 2;

            // 计算弹窗位置（居中于光点）
            let left = locationCenterX - popupRect.width / 2;
            let top = locationRect.top - popupRect.height - 10; // 默认显示在上方

            // 边界检测 - 基于viewport边界
            const margin = 10;

            // 水平边界检测
            if (left < viewportRect.left + margin) {
                left = viewportRect.left + margin;
            } else if (left + popupRect.width > viewportRect.right - margin) {
                left = viewportRect.right - popupRect.width - margin;
            }

            // 垂直边界检测 - 优先显示在上方，空间不足时显示在下方
            if (top < viewportRect.top + margin) {
                // 上方空间不足，改为显示在下方
                top = locationRect.bottom + 10;

                // 检查下方是否也超出边界
                if (top + popupRect.height > viewportRect.bottom - margin) {
                    // 如果下方也超出，则显示在viewport内能容纳的最佳位置
                    if (locationCenterY < viewportRect.top + viewportRect.height / 2) {
                        // 光点在上半部分，弹窗显示在下方
                        top = Math.min(locationRect.bottom + 10, viewportRect.bottom - popupRect.height - margin);
                    } else {
                        // 光点在下半部分，弹窗显示在上方
                        top = Math.max(locationRect.top - popupRect.height - 10, viewportRect.top + margin);
                    }
                }
            }

            // 设置最终位置
            popup.style.left = left + 'px';
            popup.style.top = top + 'px';

            // 点击其他地方关闭弹窗
            setTimeout(() => {
                document.addEventListener('click', closeLocationInfo);
            }, 100);
        }

        // 关闭地点信息弹窗 - 新增
        function closeLocationInfo(e) {
            const popup = document.getElementById('location-info-popup');
            if (!popup.contains(e.target)) {
                popup.classList.remove('show');
                document.removeEventListener('click', closeLocationInfo);
            }
        }

        // 前往地点 - 新增
        function goToLocation(locationId) {
            // 关闭弹窗
            const popup = document.getElementById('location-info-popup');
            popup.classList.remove('show');
            document.removeEventListener('click', closeLocationInfo);

            // 更新userLocation
            userLocation = locationId;  // 新增：更新用户位置

            // 切换场景
            switchScene(locationId);
        }

        // 设置地点悬停和点击事件 - 修改
        function setupLocationEvents() {
            const locations = document.querySelectorAll('.location');

            locations.forEach(location => {
                let touchTimer = null;

                // PC端鼠标事件
                location.addEventListener('mouseenter', function(e) {
                    if (!('ontouchstart' in window)) {
                        showLocationInfo(this.id, e);
                    }
                });

                location.addEventListener('mouseleave', function() {
                    if (!('ontouchstart' in window)) {
                        // PC端不自动关闭，让用户可以点击前往按钮
                    }
                });

                // 移动端触摸事件
                location.addEventListener('touchstart', function(e) {
                    e.preventDefault();
                    e.stopPropagation();

                    // 清除之前的定时器
                    if (touchTimer) {
                        clearTimeout(touchTimer);
                    }

                    // 显示地点信息
                    showLocationInfo(this.id, e);
                });

                // PC端点击事件
                location.addEventListener('click', function(e) {
                    if (!('ontouchstart' in window)) {
                        e.preventDefault();
                        e.stopPropagation();
                        showLocationInfo(this.id, e);
                    }
                });
            });
        }
        // 自由行动输入框自适应高度
        document.getElementById('free-action-input').addEventListener('input', function() {
            // 重置高度
            this.style.height = 'auto';
            // 设置新高度
            const scrollHeight = this.scrollHeight;
            this.style.height = Math.min(scrollHeight, 120) + 'px';
        });

        // 发送自由行动
        async function sendFreeAction() {
            const inputElement = document.getElementById('free-action-input');
            const actionContent = inputElement.value.trim();

            if (!actionContent) {
                alert('请输入自由行动内容！');
                return;
            }

            // 获取当前场景
            const activeScene = document.querySelector('.scene.active');
            let currentLocation = '';
            let npcsPresent = '无';

            if (activeScene.id === 'map-scene') {
                // 在地图界面
                currentLocation = '天山派（地图）';
                npcsPresent = '无在场NPC';
            } else {
                // 在具体场景
                const sceneName = activeScene.id.replace('-scene', '');
                currentLocation = locationNames[sceneName] || sceneName;

                // 获取在场NPC
                const npcsAtLocation = getNpcsAtLocation(sceneName);
                if (npcsAtLocation.length > 0) {
                    npcsPresent = npcsAtLocation.map(npc => npc.name).join('、');
                }
            }

            // 构建显示信息
            const year = Math.floor((currentWeek - 1) / 48) + 1;
            const remainingWeeks = (currentWeek - 1) % 48;
            const month = Math.floor(remainingWeeks / 4) + 1;
            const week = remainingWeeks % 4 + 1;

            const resultMessage = `时间：第${year}年第${month}月第${week}周<br>` +
                `地点：${currentLocation}<br>` +
                `{{user}}自由行动："${actionContent}"<br>` +
                `在场NPC：${npcsPresent}`;

            // 清空输入框并重置高度
            inputElement.value = '';
            inputElement.style.height = 'auto';

            // 显示结果弹窗
            await handleMessageOutput(resultMessage);
        }

        // 支持Enter键发送（Shift+Enter换行）
        document.getElementById('free-action-input').addEventListener('keydown', function(e) {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendFreeAction();
            }
        });

        // 初始化
        window.onload = async function(){
            await loadOrInitGameData();          //  NEW 先保证数据就绪
            checkAllValueRanges();
            updateAllDisplays();
            setupLocationEvents();

            // 在渲染环境下隐藏刷新NPC按钮
            if (isInRenderEnvironment()) {
                const refreshBtn = document.querySelector('.refresh-npc-btn');
                if (refreshBtn) {
                    refreshBtn.style.display = 'none';
                }
            }

            if (userLocation === 'tianshanpai'){
                document.getElementById('map-scene').classList.add('active');
            }else{
                switchScene(userLocation);
            }
            parseLLMResponse(llmResponse, mainText);
        };
    </script>
